// Package icons holds go-draw's icon set: monochrome 24x24 SVG files, one
// per registry row in icons.yaml, embedded into the binary.
//
// The app rasterises a file into an alpha mask and tints it with a theme
// colour, so colour inside a file is meaningless. The package is pure data
// and imports nothing, so any layer may name an icon. Constants are
// generated by `just icons-gen`; see .claude/skills/go-draw-icons/SKILL.md.
package icons

import "embed"

//go:embed *.svg
var files embed.FS

// Name identifies an icon: kebab-case "<category>-<thing>", which is also
// the file name without ".svg" and the registry key.
type Name string

// SVG returns the source of the named icon, or nil if there is no such icon.
func SVG(name Name) []byte {
	b, err := files.ReadFile(string(name) + ".svg")
	if err != nil {
		return nil
	}
	return b
}
